export const Actions: Story = {
  parameters: {
    docs: {
      description: { story: "Place message-level actions in `MessageFooter`, such as copy, retry, or feedback buttons." },
      source: { code: "import { CopyButton } from "@/registry/erbium/blocks/copy-button";
import { Icon } from "@/registry/erbium/ui/icon";

import { Bubble, BubbleContent } from "@/registry/erbium/ui/bubble";
import { Button } from "@/registry/erbium/ui/button";
import { Message, MessageContent, MessageFooter } from "@/registry/erbium/ui/message";

